def chain_follows_chain(chain):
    tokens = list(chain)
    tokens.sort()
    result = []
    for token in tokens:
        if result and result[-1] == token:
            result.append(token)
        else:
            result.append(token)
    return ','.join(result)

# Example usage:
# print(chain_follows_chain((bbb, ccc)))  # Output: aaa, bbb, ccc, ddd
